function validate(input) {
  const [n, threads, starts] = input;
  if (!Number.isInteger(n) || n < 1 || n > 50) return 'n must be an integer from 1 to 50.';
  if (threads.length !== 4 || [...threads].sort().join() !== 'buzz,fizz,fizzbuzz,number') return 'threads must list "fizz", "buzz", "fizzbuzz" and "number" once each.';
  if (starts.length !== 4) return 'starts needs 4 start times, one per thread.';
  if (!starts.every((t) => Number.isInteger(t) && t >= 0 && t <= 1000)) return 'Each start time is an integer from 0 to 1000 ms.';
  return null;
}

