function adapt(input, solve, kit) {
  const [n, threads, starts] = input, start = Date.now(), prints = [];
  const fizzBuzz = new solve(n);
  for (const name of threads) if (!fizzBuzz || typeof fizzBuzz[name] !== 'function') throw new Error(`FizzBuzz needs a method ${name}.`);
  let failure = null;
  threads.forEach((name, i) => {
    const record = (token) => {
      prints.push({ token, t: Date.now() - start });
      kit.trace(`${name}() prints ${token}`);
    };
    const callback = name === 'number'
      ? (x) => {
        if (!Number.isInteger(x) || x < 1 || x > n || x % 3 === 0 || x % 5 === 0) failure = failure ?? `number() may not print ${x}.`;
        record(x);
      }
      : () => record(name);
    setTimeout(() => {
      kit.trace(`The ${name} thread starts and calls ${name}()`);
      const result = fizzBuzz[name](callback);
      if (result && typeof result.then === 'function') result.then(null, (error) => { failure = failure ?? `${name}() failed: ${error && error.message || error}`; });
    }, starts[i]);
  });
  // A correct solution has printed everything by the last start; the extra time shows late prints.
  return new Promise((resolve, reject) => setTimeout(() => {
    if (failure) reject(new Error(failure));
    else resolve({ output: prints.map((p) => p.token), times: prints.map((p) => p.t) });
  }, Math.max(...starts) + 50));
}

