class FizzBuzz {
  constructor(n) {
    this.n = n;
    this.current = 1;
    this.waiting = new Map();
  }

  waitFor(i) {
    if (this.current === i) return Promise.resolve();
    return new Promise((resolve) => {
      this.waiting.set(i, resolve);
    });
  }

  advance() {
    this.current += 1;
    const wake = this.waiting.get(this.current);
    this.waiting.delete(this.current);
    if (wake) wake();
  }

  async fizz(printFizz) {
    for (let i = 3; i <= this.n; i += 3) {
      if (i % 5 === 0) continue;
      await this.waitFor(i);
      printFizz();
      this.advance();
    }
  }

  async buzz(printBuzz) {
    for (let i = 5; i <= this.n; i += 5) {
      if (i % 3 === 0) continue;
      await this.waitFor(i);
      printBuzz();
      this.advance();
    }
  }

  async fizzbuzz(printFizzBuzz) {
    for (let i = 15; i <= this.n; i += 15) {
      await this.waitFor(i);
      printFizzBuzz();
      this.advance();
    }
  }

  async number(printNumber) {
    for (let i = 1; i <= this.n; i++) {
      if (i % 3 === 0 || i % 5 === 0) continue;
      await this.waitFor(i);
      printNumber(i);
      this.advance();
    }
  }
}

