class FizzBuzz {
  constructor(n) {
    this.n = n;
    this.next = 1;
    this.printers = new Map();
  }

  owner(i) {
    if (i % 15 === 0) return 'fizzbuzz';
    if (i % 3 === 0) return 'fizz';
    if (i % 5 === 0) return 'buzz';
    return 'number';
  }

  // Record the arriving printer, then print every token whose owner has arrived.
  arrive(name, print) {
    this.printers.set(name, print);
    while (this.next <= this.n && this.printers.has(this.owner(this.next))) {
      const i = this.next++;
      const owner = this.owner(i);
      if (owner === 'number') this.printers.get('number')(i);
      else this.printers.get(owner)();
    }
  }

  fizz(printFizz) { this.arrive('fizz', printFizz); }
  buzz(printBuzz) { this.arrive('buzz', printBuzz); }
  fizzbuzz(printFizzBuzz) { this.arrive('fizzbuzz', printFizzBuzz); }
  number(printNumber) { this.arrive('number', printNumber); }
}

